USE CATALOG dcp_synth; CREATE OR REPLACE VIEW `04_presentation`.vw_regulatory_portfolio_summary AS SELECT market,authority,workflow_stage,risk_status,COUNT(*) submission_count,COUNT_IF(risk_status='AT_RISK') at_risk_count,MAX(updated_at) refreshed_at FROM `03_gold`.dp19_regulatory_submission_master GROUP BY market,authority,workflow_stage,risk_status; CREATE OR REPLACE VIEW `04_presentation`.vw_regulatory_submission_queue AS SELECT submission_id,product_id,market,authority,workflow_stage,owner,risk_status,authority_due_date FROM `03_gold`.dp19_regulatory_submission_master WHERE risk_status='AT_RISK'; CREATE OR REPLACE VIEW `04_presentation`.vw_authority_interaction_queue AS SELECT interaction_id,submission_id,product_id,market,authority,interaction_type,response_due_date,status FROM `03_gold`.dp21_regulatory_authority_interactions WHERE status<>'CLOSED';